#prepping for graph 1#

headcoachlist |&gt; 
  gt() |&gt; 
  tab_header(
    title = "NFL coaches that got canned during the season",
    subtitle = "Since 2010, 35 different NFL coaches have been fired midseason. It's happened more than once to a few poor souls."
  ) |&gt; tab_style(
    style = cell_text(color = "black", weight = "bold", align = "left"),
    locations = cells_title("title")
  ) |&gt; tab_style(
    style = cell_text(color = "black", align = "left"),
    locations = cells_title("subtitle")
  ) |&gt;
  tab_source_note(
    source_note = md("**By:** Danny Berg  |  **Source:** SportsReference")
  ) |&gt; 
  tab_style(
    style = list(
      cell_text(weight = "bold", size = 12),
      cell_borders(sides = "bottom", weight = px(3))
    ),
    locations = cells_column_labels(columns = everything())
  ) |&gt;
  tab_style(
    style = cell_borders(sides = "right", color = "black", weight = px(2)),
    locations = cells_body(columns = 2)
  ) |&gt; 
  tab_style(
    style = cell_borders(sides = "right", color = "black", weight = px(2)),
    locations = cells_body(columns = 4)
  ) |&gt; 
  tab_style(
    style = cell_borders(sides = "right", color = "darkgrey", weight = px(2)),
    locations = cells_body(columns = 6)
  ) |&gt; 
    data_color(
    columns = vars(`Season Wins`),
