  mutate(TeamSeason = paste(Team, Season))

ggplot() + 
  geom_vline(data=fireddates, aes(xintercept=Fired), color="blue") +
  geom_line(data=master, aes(x=Gtm, y=PD, group=TeamSeason)) + 
